def vendor_invoice_key(number, day):
    """Frozen copy of purchasing.models.vendor_invoice_key as this migration keyed: any case, no spaces, - / or ., per April year."""
    key = re.sub(r"[\s\-/.]", "", number or "").upper()
    if not key:
        return ""
    if day is None:
        return f":{key}"
    return f"{day.year if day.month >= 4 else day.year - 1}:{key}"


def key_the_invoices_billed(apps, schema_editor):
    """
    Each bill's vendor invoice number, keyed within its year (O95).

    The constraint this replaces was exact, so "INV-77" and "inv-77" of one
    vendor could both stand, and posted bills cannot be edited. Where the
    key makes two bills one invoice, the earliest keeps it and the rest are
    left unkeyed, so the new constraint does not apply to them, and are
    reported by number: nothing merged, nothing crashed. Saving one of them
    again as a draft keys it and refuses it in words, naming the other.
    """
    Bill = apps.get_model("purchasing", "Bill")
    kept, left = {}, []
    for bill in (Bill.objects.filter(debits__isnull=True).exclude(reference="")
                 .only("vendor_id", "number", "reference", "bill_date").order_by("bill_date", "pk")):
        key = vendor_invoice_key(bill.reference, bill.bill_date)
        if not key:
            continue
        first = kept.setdefault((bill.vendor_id, key), bill)
        if first.pk != bill.pk:
            left.append((first, bill))
            continue
        Bill.objects.filter(pk=bill.pk).update(reference_key=key)
    for first, bill in left:
        print(f"purchasing 0076: {bill.number or bill.pk} bills vendor invoice {bill.reference!r}, which is "
              f"{first.reference!r} on {first.number or first.pk} of the same vendor and year; left unkeyed, "
              "not merged. Check whether the vendor was paid twice.")


